import{z as s,x as d,o as a,c as r,q as p,j as B,D as l,d as E,s as i,S as A,b as o}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"epoll","description":"","frontmatter":{"title":"epoll","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/epoll.md","filePath":"cs/epoll.md","lastUpdated":1791063341000}'),n={name:"cs/epoll.md"};function c(_,e,T,m,f,C){const t=d("Mermaid");return a(),r("div",null,[e[2]||(e[2]=p('<h1 id="epoll" tabindex="-1">epoll <a class="header-anchor" href="#epoll" aria-label="Permalink to &quot;epoll&quot;">​</a></h1><div class="epigraph"><p>在内核为进程保存兴趣表；就绪事件放进队列，wait 不必每次携带并扫描全部描述符。</p><footer>—— 据 Linux epoll 手册；Stevens 对大规模事件通知的讨论</footer></div><p><a href="/cs/select-poll">上一课</a>每次把 n 个 fd 拷进内核做 O(n) 扫描。连接数上万时，扫描本身比工作还重。缺口是 <strong>epoll</strong>：<code>epoll_ctl</code> 改兴趣，<code>epoll_wait</code> 只取已就绪。合并水平与边沿触发，不当两篇词条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>select 的兴趣是调用参数，无状态。epoll 实例是一个 fd，内核红黑树（或等价）记住监视哪些 fd、要哪些事件。文件真正就绪时，回调把该项放进就绪链表。wait 只收割链表。缺口不是新的管道，而是这份内核状态以及 ET（边沿：只在状态变化时报告）与 LT（水平：与 poll 相同）的差别。</p><p><span class="marginnote">「水平触发」与「边沿触发」两个词借自电路：水平触发看「现在的电平」，条件还成立就一直报；边沿触发只看「变化的瞬间」，从无到有那一下报一次。epoll 的 ET/LT 正是这两个词的缩写——LT 像一直按着的门铃，ET 像只响一声的门铃。</span></p><p>本课不把 <code>epoll_ctl</code> 每个 op 的错误码背完。</p><p><span class="marginnote">ET 要求一次读到 EAGAIN，否则事件丢失在应用逻辑里。LT 更不易用错，就绪队列可能反复报告同一 fd。本课不写攻击，只写语义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>epoll_create</code> → 对每个连接 <code>EPOLL_CTL_ADD</code> → 循环 <code>epoll_wait</code> → 对返回的 fd 做非阻塞 <code>read</code>/<code>write</code>。关闭 fd 会自动从兴趣表删除（实现相关，教学上仍应显式 DEL）。与 <a href="/cs/sigmask">信号掩码</a> 可用 <code>epoll_pwait</code> 原子搭配。底层仍是各文件的 poll 回调，与 VFS 操作表相连。</p><p><span class="marginnote">数量级感受一下：一万个连接里只有 50 个活跃，select 每次都要把一万个 fd 拷进内核再全扫一遍；epoll_wait 只返回那 50 个就绪的。连接涨到十万，select 的固定开销涨十倍，epoll 的开销只跟着活跃数走——这正是「把兴趣表放在内核」买下的账。</span></p>',11)),(a(),B(A,null,{default:l(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTL%5B%22epoll_ctl%20%E5%85%B4%E8%B6%A3%E8%A1%A8%22%5D%20--%3E%20CB%5B%22%E6%96%87%E4%BB%B6%E5%B0%B1%E7%BB%AA%E5%9B%9E%E8%B0%83%22%5D%0A%20%20CB%20--%3E%20RQ%5B%22%E5%B0%B1%E7%BB%AA%E9%98%9F%E5%88%97%22%5D%0A%20%20RQ%20--%3E%20WAIT%5B%22epoll_wait%20%E6%94%B6%E5%89%B2%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[E("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,"epoll 把复杂度从「每次系统调用 × n」降到「事件发生时 O(1) 插入 + wait 收割」。它仍是同步 I/O 的就绪通知，不是下一课的异步提交。线程安全：同一 epoll fd 可被多线程 wait，语义要小心惊群——实现有过变化，主干只承认「有这个对象」。",-1)),(a(),B(A,null,{default:l(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E6%8E%A5%E6%94%B6%E7%BC%93%E5%86%B2%E5%8C%BA%E4%BB%8E%E7%A9%BA%E5%8F%98%E4%B8%BA%E9%9D%9E%E7%A9%BA%22%5D%20--%3E%20LT%5B%22LT%EF%BC%9A%E5%8F%AA%E8%A6%81%E8%BF%98%E6%9C%89%E6%95%B0%E6%8D%AE%EF%BC%8C%E6%AF%8F%E6%AC%A1%20wait%20%E9%83%BD%E6%8A%A5%E5%91%8A%22%5D%0A%20%20EV%20--%3E%20ET%5B%22ET%EF%BC%9A%E5%8F%AA%E5%9C%A8%E5%8F%98%E5%8C%96%E7%9E%AC%E9%97%B4%E6%8A%A5%E5%91%8A%E4%B8%80%E6%AC%A1%22%5D%0A%20%20LT%20--%3E%20SAFE%5B%22%E4%B8%8D%E6%98%93%E6%BC%8F%EF%BC%9A%E4%B8%8B%E6%AC%A1%20wait%20%E8%BF%98%E4%BC%9A%E6%8F%90%E9%86%92%22%5D%0A%20%20ET%20--%3E%20MUST%5B%22%E5%BF%85%E9%A1%BB%E5%BE%AA%E7%8E%AF%E8%AF%BB%E7%9B%B4%E5%88%B0%20EAGAIN%22%5D%0A%20%20MUST%20--%3E%7C%22%E5%81%B7%E6%87%92%E5%8F%AA%E8%AF%BB%E4%B8%80%E6%AC%A1%22%7C%20LOSE%5B%22%E5%89%A9%E4%BD%99%E6%95%B0%E6%8D%AE%E6%B2%A1%E4%BA%BA%E5%86%8D%E6%8F%90%E9%86%92%EF%BC%8C%E8%BF%9E%E6%8E%A5%E5%8D%A1%E6%AD%BB%22%5D%0A%20%20SAFE%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%20wait%20%E7%BB%A7%E7%BB%AD%E6%94%B6%E5%89%B2%22%5D%0A"})]),fallback:l(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=p('<p><span class="marginnote">初学者容易以为「换 epoll 一定更快」；连接少且个个活跃时，epoll_ctl 的日常维护反而是白付的，select/poll 未必更慢。epoll 赢在「连接海量、活跃稀疏」的负载形状——先看自己业务的形状，再选工具，别背口诀。</span></p><p>不要把 epoll 写成 Windows IOCP 的逐条对照表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>io_uring</code> 的 SQE。不保证 epoll 在所有文件类型上等价（部分设备 poll 实现粗糙）。下一课：把「等就绪再 read」换成「提交读请求，完成进队列」，进一步减少陷入。</p><p>后课默认：兴趣表可规模化。系统调用本身仍是每批 wait；下一课 io_uring 用共享环形缓冲提交与完成。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>epoll 在内核保存兴趣并维护就绪队列。</li><li>LT 似 poll；ET 只报变化，要读到 EAGAIN。</li><li>异步提交完成队列是 io_uring 的缺口。</li><li>出处：Linux <code>epoll(7)</code>；Stevens；Love, <em>LKD</em>。</li></ul>',7))])}const u=s(n,[["render",c]]);export{h as __pageData,u as default};
